// Mesafe alarmı: nesne yaklaştıkça buzzer daha sık öter
const int TRIG = 7;
const int ECHO = 6;
const int BUZZER = 8;   // aktif buzzer
const int ALARM_CM = 30;

float mesafeOlc() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);

  long sure = pulseIn(ECHO, HIGH, 30000);   // en fazla 30 ms bekle
  if (sure == 0) return -1;                  // yankı gelmedi
  return sure * 0.0343 / 2.0;                // ses hızı: 0,0343 cm/µs, gidiş-dönüş /2
}

void setup() {
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(BUZZER, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  float cm = mesafeOlc();
  Serial.println(cm);

  if (cm > 0 && cm < ALARM_CM) {
    digitalWrite(BUZZER, HIGH);
    delay(40);
    digitalWrite(BUZZER, LOW);
    // yakınsa kısa, uzaksa uzun ara
    delay(map((long)cm, 2, ALARM_CM, 40, 500));
  } else {
    digitalWrite(BUZZER, LOW);
    delay(100);
  }
}
